76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /**
82	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
83	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
84	     */
85	    private static final Pattern EMAIL_PATTERN =
86	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
87	
88	    /**
89	     * Email domains rejected as disposable/throwaway addresses. An owner whose email domain matches
90	     * one of these (compared case-insensitively) is rejected with 400.
91	     */
92	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
93	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
94	
95	    /**
96	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
97	     * new owner's id, customerCode, registrationDate, membershipLevel and membershipNumber.
98	     */
99	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
100	
101	    /**
102	     * Common street-type abbreviations expanded during address normalization, keyed by the
103	     * upper-cased abbreviation.
104	     */
105	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
106	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
107	
108	    /**
109	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
110	     * city already holds this many owners.
111	     */
112	    private static final int CITY_CAPACITY = 50;
113	
114	    /**
115	     * Maximum number of owners that may be created on a single day. A create is rejected once this
116	     * many owners already carry the current day as their {@code registrationDate}.
117	     */
118	    private static final int DAILY_OWNER_LIMIT = 100;
119	
120	    /**
121	     * Fixed public holidays that the business-day roll skips: when an adjusted registration date lands
122	     * on one of these it advances to the next non-holiday business day.
123	     */
124	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
125	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
126	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
127	
128	    private final ClinicService clinicService;
129	
130	    private final OwnerMapper ownerMapper;
131	
132	    private final PetMapper petMapper;
133	
134	    private final VisitMapper visitMapper;
135	
136	    /**
137	     * Remembers the id of the owner created under each seen {@code Idempotency-Key}, so a create that
138	     * repeats with an already-seen key returns the originally created owner instead of creating a
139	     * duplicate.
140	     */
141	    private final Map<String, Integer> ownersByIdempotencyKey = new ConcurrentHashMap<>();
142	
143	    public OwnerRestControllerV1(ClinicService clinicService,
144	                                 OwnerMapper ownerMapper,
145	                                 PetMapper petMapper,
146	                                 VisitMapper visitMapper) {
147	        this.clinicService = clinicService;
148	        this.ownerMapper = ownerMapper;
149	        this.petMapper = petMapper;
150	        this.visitMapper = visitMapper;
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
156	        Collection<Owner> owners;
157	        if (lastName != null) {
158	            owners = this.clinicService.findOwnerByLastName(lastName);
159	        } else {
160	            owners = this.clinicService.findAllOwners();
161	        }
162	        if (owners.isEmpty()) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
181	        String idempotencyKey = currentIdempotencyKey();
182	        if (idempotencyKey != null) {
183	            Integer existingId = ownersByIdempotencyKey.get(idempotencyKey);
184	            if (existingId != null) {
185	                Owner existing = this.clinicService.findOwnerById(existingId);
186	                if (existing != null) {
187	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
188	                }
189	            }
190	        }
191	        validateRequiredFields(ownerFieldsDto);
192	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
193	        HttpHeaders headers = new HttpHeaders();
194	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
195	        applyAddress(owner, ownerFieldsDto);
196	        rejectFutureRegistrationDate(owner.getRegistrationDate());
197	        LocalDate effectiveDate = owner.getRegistrationDate() == null
198	            ? LocalDate.now()
199	            : owner.getRegistrationDate();
200	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
201	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
202	        rejectWhenCityAtCapacity(owner.getCity());
203	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
204	        applyHousehold(owner);
205	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
206	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
207	        rejectDuplicateIdentity(owner);
208	        owner.setCustomerCode(customerCode(owner));
209	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
210	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
211	        flagPossibleDuplicate(owner, sharesHousehold);
212	        this.clinicService.saveOwner(owner);
213	        if (idempotencyKey != null) {
214	            ownersByIdempotencyKey.put(idempotencyKey, owner.getId());
215	        }
216	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
217	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
218	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
219	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
220	        headers.setLocation(UriComponentsBuilder.newInstance()
221	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
222	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
223	    }
224	
225	    /**
226	     * Reads the {@code Idempotency-Key} header of the request currently being handled, returning
227	     * {@code null} when the header is absent or blank (or there is no bound request). A non-blank
228	     * value opts the create into idempotent replay via {@link #ownersByIdempotencyKey}.
229	     *
230	     * @return the trimmed idempotency key, or {@code null} when none was supplied
231	     */
232	    private String currentIdempotencyKey() {
233	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
234	            return null;
235	        }
236	        String key = attrs.getRequest().getHeader("Idempotency-Key");
237	        return isBlank(key) ? null : key.trim();
238	    }
239	
240	    /**
241	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
242	     * code derived from the owner's postcode (falling back to the city-to-region table, then
243	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
244	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}).
245	     *
246	     * <p>Should the computed code collide with an existing owner's {@code customerCode}, it is
247	     * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
248	     * unique (e.g. {@code NSW-1A2B3C4D-2}), so distinct owners always receive distinct customer codes.
249	     *
250	     * @param owner the owner being created, with its normalized telephone already applied
251	     * @return the assigned, de-duplicated customer code
252	     */
253	    private String customerCode(Owner owner) {
254	        String base = regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
255	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
256	            .map(Owner::getCustomerCode)
257	            .filter(code -> code != null)
258	            .collect(java.util.stream.Collectors.toSet());
259	        if (!existingCodes.contains(base)) {
260	            return base;
261	        }
262	        int n = 2;
263	        while (existingCodes.contains(base + "-" + n)) {
264	            n++;
265	        }
266	        return base + "-" + n;
267	    }
268	
269	    /**
270	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
271	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
272	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
273	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
274	     * postcode nor the city identifies a region.
275	     *
276	     * @param owner the owner being created
277	     * @return the derived region code, never {@code null}
278	     */
279	    private String regionCode(Owner owner) {
280	        String fromPostcode = regionFromPostcode(owner.getPostcode());
281	        if (fromPostcode != null) {
282	            return fromPostcode;
283	        }
284	        String fromCity = region(owner.getCity());
285	        return fromCity == null ? "UNKNOWN" : fromCity;
286	    }
287	
288	    /**
289	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
290	     * postcode is absent, not 4 digits, or in no known range.
291	     *
292	     * @param postcode the owner's postcode, may be {@code null}
293	     * @return the region code, or {@code null} when no known range contains the postcode
294	     */
295	    private String regionFromPostcode(String postcode) {
296	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
297	            return null;
298	        }
299	        int value = Integer.parseInt(postcode);
300	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
301	            int[] range = entry.getValue();
302	            if (value >= range[0] && value <= range[1]) {
303	                return entry.getKey();
304	            }
305	        }
306	        return null;
307	    }
308	
309	    /**
310	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
311	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
312	     *
313	     * @param telephone the owner's normalized (E.164) telephone
314	     * @param lastName  the owner's last name
315	     * @return the 8-character upper-cased hex hash
316	     */
317	    private String identityHash8(String telephone, String lastName) {
318	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
319	        try {
320	            byte[] digest = MessageDigest.getInstance("SHA-256")
321	                .digest(input.getBytes(StandardCharsets.UTF_8));
322	            StringBuilder hex = new StringBuilder(digest.length * 2);
323	            for (byte b : digest) {
324	                hex.append(String.format("%02x", b));
325	            }
326	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
327	        } catch (NoSuchAlgorithmException ex) {
328	            throw new IllegalStateException("SHA-256 not available", ex);
329	        }
330	    }
331	
332	    /**
333	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
334	     * last two digits of the fiscal year of the owner's business-day-adjusted registration date,
335	     * zero-padded (e.g. {@code NSW-1A2B3C4D-M26}). The fiscal year starts on 1 July.
336	     *
337	     * @param customerCode     the owner's assigned customer code
338	     * @param registrationDate the owner's business-day-adjusted registration date
339	     * @return the assigned membership number
340	     */
341	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
342	        return String.format("%s-M%02d", customerCode, fiscalYear(registrationDate) % 100);
343	    }
344	
345	    /**
346	     * The month the fiscal year starts on (1 July).
347	     */
348	    private static final int FISCAL_YEAR_START_MONTH = 7;
349	
350	    /**
351	     * Derives the fiscal year of the given date. The fiscal year starts on 1 July, so a date on or
352	     * after 1 July belongs to the following calendar year's fiscal year (e.g. 2026-07-01 is fiscal
353	     * year 2027) while an earlier date takes the calendar year unchanged.
354	     *
355	     * @param date the date to derive the fiscal year of
356	     * @return the fiscal year
357	     */
358	    private int fiscalYear(LocalDate date) {
359	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
360	    }
361	
362	    /**
363	     * Counts the existing owners that already share the given firstName and lastName, compared
364	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
365	     * the owners that pre-existed this create.
366	     *
367	     * @param firstName the new owner's first name
368	     * @param lastName  the new owner's last name
369	     * @return the number of existing namesakes
370	     */
371	    private int countNamesakes(String firstName, String lastName) {
372	        return (int) this.clinicService.findAllOwners().stream()
373	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
374	                && equalsIgnoreCase(existing.getLastName(), lastName))
375	            .count();
376	    }
377	
378	    /**
379	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
380	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
381	     * still resemble an existing owner: when it shares an existing owner's lastName (compared
382	     * case-insensitively) and postcode while carrying a different telephone, the owner is flagged
383	     * with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing
384	     * owner's id. When no such owner exists the flag is set to {@code false} and no match id is
385	     * recorded. An owner with no postcode can never soft-match and is always {@code false}.
386	     *
387	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
388	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
389	     * always flagged {@code false}.
390	     *
391	     * @param owner           the owner being created, with its normalized telephone already applied
392	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
393	     *                        never flagged as a possible duplicate
394	     */
395	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
396	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
397	        if (match != null) {
398	            owner.setPossibleDuplicate(true);
399	            owner.setPossibleDuplicateOf(match.getId());
400	        } else {
401	            owner.setPossibleDuplicate(false);
402	            owner.setPossibleDuplicateOf(null);
403	        }
404	    }
405	
406	    /**
407	     * Finds the existing owner this owner soft-matches: same lastName (case-insensitive) and same
408	     * postcode, but a different telephone. When several existing owners match, the one with the
409	     * lowest id is chosen so the result is deterministic. Returns {@code null} when the owner has no
410	     * postcode or no such existing owner exists.
411	     *
412	     * @param owner the owner being created
413	     * @return the matching existing owner, or {@code null} when there is no soft-match
414	     */
415	    private Owner findPossibleDuplicate(Owner owner) {
416	        if (isBlank(owner.getPostcode())) {
417	            return null;
418	        }
419	        return this.clinicService.findAllOwners().stream()
420	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
421	                && owner.getPostcode().equals(existing.getPostcode())
422	                && !equalsIgnoreCase(existing.getTelephone(), owner.getTelephone()))
423	            .min(Comparator.comparing(Owner::getId))
424	            .orElse(null);
425	    }
426	
427	    /**
428	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
429	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
430	     * customer-code sequence is derived.
431	     *
432	     * @param city the new owner's city
433	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
434	     */
435	    private void rejectWhenCityAtCapacity(String city) {
436	        long count = this.clinicService.findAllOwners().stream()
437	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
438	            .count();
439	        if (count >= CITY_CAPACITY) {
440	            throw new CityAtCapacityException(city);
441	        }
442	    }
443	
444	    /**
445	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
446	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
447	     * business-day registration date, so the limit is enforced per business day and weekend
448	     * requests count against the Monday they roll forward to.
449	     *
450	     * @param registrationDate the owner's adjusted (business-day) registration date
451	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
452	     *                                  registration date
453	     */
454	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
455	        long count = this.clinicService.findAllOwners().stream()
456	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
457	            .count();
458	        if (count >= DAILY_OWNER_LIMIT) {
459	            throw new DailyOwnerLimitException(registrationDate);
460	        }
461	    }
462	
463	    /**
464	     * Rejects creating an owner whose supplied {@code registrationDate} lies in the future, i.e. is
465	     * later than the current server date. A {@code null} registration date is accepted (it defaults
466	     * to the server date) and today or any past date is allowed; only a future value is rejected.
467	     *
468	     * @param registrationDate the registration date supplied on the request, may be {@code null}
469	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
470	     */
471	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
472	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
473	            throw new FutureRegistrationDateException(registrationDate);
474	        }
475	    }
476	
477	    /**
478	     * Rolls a registration date forward onto a business day: while it falls on a Saturday, a Sunday or
479	     * a listed {@link #PUBLIC_HOLIDAYS public holiday} it advances one day at a time until it lands on
480	     * a non-holiday weekday, otherwise it is returned unchanged. Applied to the effective registration
481	     * date (whether supplied in the request or defaulted to the server date) so a weekend or holiday
482	     * value never persists as an owner's {@code registrationDate}.
483	     *
484	     * @param date the effective registration date
485	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
486	     */
487	    private LocalDate toBusinessDay(LocalDate date) {
488	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
489	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
490	            || PUBLIC_HOLIDAYS.contains(date)) {
491	            date = date.plusDays(1);
492	        }
493	        return date;
494	    }
495	
496	    private boolean equalsIgnoreCase(String a, String b) {
497	        return a == null ? b == null : a.equalsIgnoreCase(b);
498	    }
499	
500	    /**
501	     * Whether an existing owner has been soft-deleted. A soft-deleted owner retains its row but is
502	     * ignored by the create endpoint's duplicate and identity checks, so a normally-blocking match
503	     * against a deleted owner is allowed.
504	     *
505	     * @param owner an existing owner
506	     * @return {@code true} when the owner is flagged deleted
507	     */
508	    private boolean isDeleted(Owner owner) {
509	        return Boolean.TRUE.equals(owner.getDeleted());
510	    }
511	
512	    /**
513	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
514	     * offending field so the client learns about all of them at once.
515	     *
516	     * <p>An address may be supplied in either form: the structured {@code addressLine1} or the flat
517	     * {@code address}. The {@code address} error is raised only when both are missing or blank, so a
518	     * structured owner (with {@code addressLine1}) and an earlier flat owner (with {@code address})
519	     * are both accepted.
520	     *
521	     * @param ownerFieldsDto the submitted owner fields
522	     * @throws MissingOwnerFieldsException if firstName, lastName, address (in either form), city or
523	     *                                     telephone is missing or blank
524	     */
525	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
526	        List<String> errors = new ArrayList<>();
527	        if (isBlank(ownerFieldsDto.getFirstName())) {
528	            errors.add("firstName");
529	        }
530	        if (isBlank(ownerFieldsDto.getLastName())) {
531	            errors.add("lastName");
532	        }
533	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddressLine1()))
534	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
535	            errors.add("address");
536	        }
537	        if (isBlank(ownerFieldsDto.getCity())) {
538	            errors.add("city");
539	        }
540	        if (isBlank(ownerFieldsDto.getTelephone())) {
541	            errors.add("telephone");
542	        }
543	        if (!errors.isEmpty()) {
544	            throw new MissingOwnerFieldsException(errors);
545	        }
546	    }
547	
548	    private boolean isBlank(String value) {
549	        return value == null || value.isBlank();
550	    }
551	
552	    /**
553	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
554	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
555	     */
556	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
557	        "NSW", new int[] {2000, 2099},
558	        "VIC", new int[] {3000, 3099},
559	        "QLD", new int[] {4000, 4099});
560	
561	    /**
562	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
563	     * is optional and accepted, keeping the create contract backward-compatible. When present the
564	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
565	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
566	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
567	     *
568	     * @param postcode the raw postcode value as submitted, may be {@code null}
569	     * @param city     the owner's city, used to resolve the region whose range applies
570	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
571	     *                                  the city's region
572	     */
573	    private void validatePostcode(String postcode, String city) {
574	        if (isBlank(postcode)) {
575	            return;
576	        }
577	        if (!postcode.matches("[0-9]{4}")) {
578	            throw new InvalidPostcodeException(postcode, city);
579	        }
580	        String region = region(city);
581	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
582	        if (range != null) {
583	            int value = Integer.parseInt(postcode);
584	            if (value < range[0] || value > range[1]) {
585	                throw new InvalidPostcodeException(postcode, city);
586	            }
587	        }
588	    }
589	
590	    /**
591	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
592	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
593	     *
594	     * @param city the owner's city
595	     * @return the region code, or {@code null} when the city has no known region
596	     */
597	    private String region(String city) {
598	        if (city == null) {
599	            return null;
600	        }
601	        return switch (city) {
602	            case "Sydney" -> "NSW";
603	            case "Melbourne" -> "VIC";
604	            case "Brisbane" -> "QLD";
605	            default -> null;
606	        };
607	    }
608	
609	    /**
610	     * The number of national (subscriber) digits an E.164 number must carry for a given country
611	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
612	     * national digits and the North American Numbering Plan ('+1') requires 10.
613	     */
614	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
615	        Map.of("61", 9, "1", 10);
616	
617	    /**
618	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
619	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
620	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
621	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
622	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
623	     *
624	     * @param telephone the raw telephone value as submitted
625	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
626	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
627	     *                                   national-number length is wrong for its country code
628	     */
629	    private String normalizeTelephone(String telephone) {
630	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
631	        String nationalSignificantNumber;
632	        if (cleaned.startsWith("+")) {
633	            nationalSignificantNumber = cleaned.substring(1);
634	        } else {
635	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
636	            nationalSignificantNumber = "61" + national;
637	        }
638	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
639	            throw new InvalidTelephoneException(telephone);
640	        }
641	        validateNationalNumberLength(nationalSignificantNumber, telephone);
642	        return "+" + nationalSignificantNumber;
643	    }
644	
645	    /**
646	     * Validates the national-number length of an E.164 number against its country calling code. The
647	     * significant number is a country code immediately followed by the national digits; for each
648	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
649	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
650	     * left unchecked.
651	     *
652	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
653	     * @param rejectedValue             the raw telephone value, reported on rejection
654	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
655	     */
656	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
657	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
658	            String countryCode = rule.getKey();
659	            if (nationalSignificantNumber.startsWith(countryCode)) {
660	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
661	                if (nationalDigits != rule.getValue()) {
662	                    throw new InvalidTelephoneException(rejectedValue);
663	                }
664	                return;
665	            }
666	        }
667	    }
668	
669	    /**
670	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
671	     * value is treated as absent and returns {@code null}); when present the value must be a
672	     * syntactically valid address, and is stored and returned lower-cased.
673	     *
674	     * @param email the raw email value as submitted, may be {@code null}
675	     * @return the lower-cased email, or {@code null} when none was supplied
676	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
677	     */
678	    private String normalizeEmail(String email) {
679	        if (email == null || email.isBlank()) {
680	            return null;
681	        }
682	        String normalized = email.trim().toLowerCase();
683	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
684	            throw new InvalidEmailException(email);
685	        }
686	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
687	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
688	            throw new DisposableEmailException(email);
689	        }
690	        return normalized;
691	    }
692	
693	    /**
694	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
695	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
696	     * key is the normalized telephone, email and householdId joined together, this one check
697	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
698	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
699	     * with different telephones have different keys and are both allowed.
700	     *
701	     * @param owner the owner being created, with its normalized telephone, email and householdId
702	     *              already applied
703	     * @throws DuplicateIdentityException if another owner already has the same identityKey
704	     */
705	    private void rejectDuplicateIdentity(Owner owner) {
706	        String identityKey = identityKey(owner);
707	        boolean inUse = this.clinicService.findAllOwners().stream()
708	            .filter(existing -> !isDeleted(existing))
709	            .map(this::identityKey)
710	            .anyMatch(identityKey::equals);
711	        if (inUse) {
712	            throw new DuplicateIdentityException(identityKey);
713	        }
714	    }
715	
716	    /**
717	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
718	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
719	     * duplicate decision is made by comparing whole identityKeys.
720	     *
721	     * @param owner the owner whose identityKey to derive
722	     * @return the derived identityKey
723	     */
724	    private String identityKey(Owner owner) {
725	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
726	        String email = owner.getEmail() == null ? "" : owner.getEmail();
727	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
728	        return telephone + "|" + email + "|" + householdId;
729	    }
730	
731	    /**
732	     * Applies the household rule to an owner being created. The household is keyed on
733	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
734	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
735	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
736	     *
737	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
738	     * same householdId is a member of the same household. A new owner sharing an existing household
739	     * is admitted as a further member of it — its membership level is then capped by the household
740	     * (see {@code OwnerMapper#membershipLevel}) rather than the create being rejected.
741	     *
742	     * @param owner the owner being created
743	     */
744	    private void applyHousehold(Owner owner) {
745	        owner.setHouseholdId(householdId(owner));
746	    }
747	
748	    /**
749	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
750	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
751	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
752	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
753	     * creation order. A {@code null} postcode contributes an empty segment.
754	     *
755	     * @param owner the owner whose household identifier to derive
756	     * @return the household identifier
757	     */
758	    private String householdId(Owner owner) {
759	        String lastNameKey = toHouseholdKey(owner.getLastName());
760	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
761	        try {
762	            byte[] digest = MessageDigest.getInstance("SHA-256")
763	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
764	            StringBuilder hex = new StringBuilder(digest.length * 2);
765	            for (byte b : digest) {
766	                hex.append(String.format("%02x", b));
767	            }
768	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
769	        } catch (NoSuchAlgorithmException ex) {
770	            throw new IllegalStateException("SHA-256 not available", ex);
771	        }
772	    }
773	
774	    /**
775	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
776	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
777	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
778	     * string.
779	     */
780	    private String toHouseholdKey(String value) {
781	        if (value == null) {
782	            return "";
783	        }
784	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
785	    }
786	
787	    /**
788	     * Applies the owner's address, preferring the structured form over the flat one. The structured
789	     * {@code addressLine1}/{@code addressLine2} and the flat {@code address} are each normalized (see
790	     * {@link #normalizeAddress(String)}). When a non-blank {@code addressLine1} is supplied the
791	     * structured form wins: {@code addressLine1} and {@code addressLine2} are stored normalized (a
792	     * blank {@code addressLine2} is stored as {@code null}), and the composed {@code address} is the
793	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
794	     * appended when an {@code addressLine2} is present. Otherwise the flat {@code address} is used for
795	     * backward compatibility: the normalized flat value becomes both {@code addressLine1} and the
796	     * stored {@code address}, with no {@code addressLine2}. Everything that later reads the owner's
797	     * address therefore sees the structured value when present, falling back to the flat one.
798	     *
799	     * @param owner the owner being created
800	     * @param dto   the submitted owner fields
801	     */
802	    private void applyAddress(Owner owner, OwnerFieldsDto dto) {
803	        String line1 = normalizeAddress(dto.getAddressLine1());
804	        String line2 = normalizeAddress(dto.getAddressLine2());
805	        String flat = normalizeAddress(dto.getAddress());
806	        String effectiveLine1 = line1.isEmpty() ? flat : line1;
807	        String effectiveLine2 = line1.isEmpty() ? "" : line2;
808	        String composed = effectiveLine2.isEmpty()
809	            ? effectiveLine1
810	            : effectiveLine1 + " " + effectiveLine2;
811	        owner.setAddressLine1(effectiveLine1.isEmpty() ? null : effectiveLine1);
812	        owner.setAddressLine2(effectiveLine2.isEmpty() ? null : effectiveLine2);
813	        owner.setAddress(composed);
814	    }
815	
816	    /**
817	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
818	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
819	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
820	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
821	     * value, or one that is blank once trimmed, normalizes to an empty string.
822	     *
823	     * @param address the raw address value as submitted, may be {@code null}
824	     * @return the normalized address, or an empty string when none was supplied
825	     */
826	    private String normalizeAddress(String address) {
827	        if (address == null) {
828	            return "";
829	        }
830	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
831	        if (collapsed.isEmpty()) {
832	            return "";
833	        }
834	        String[] tokens = collapsed.split(" ");
835	        StringBuilder normalized = new StringBuilder(collapsed.length());
836	        for (int i = 0; i < tokens.length; i++) {
837	            if (i > 0) {
838	                normalized.append(' ');
839	            }
840	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
841	        }
842	        return normalized.toString();
843	    }
844	
845	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
846	    @Override
847	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
848	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
849	        if (currentOwner == null) {
850	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
851	        }
852	        currentOwner.setAddress(ownerFieldsDto.getAddress());
853	        currentOwner.setCity(ownerFieldsDto.getCity());
854	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
855	        currentOwner.setLastName(ownerFieldsDto.getLastName());
856	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
857	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
858	        this.clinicService.saveOwner(currentOwner);
859	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
860	    }
861	
862	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
863	    @Transactional
864	    @Override
865	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
866	        Owner owner = this.clinicService.findOwnerById(ownerId);
867	        if (owner == null) {
868	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
869	        }
870	        owner.setDeleted(true);
871	        this.clinicService.saveOwner(owner);
872	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
873	    }
874	
875	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
876	    @Override
877	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
878	        Owner owner = this.clinicService.findOwnerById(ownerId);
879	        if (owner == null) {
880	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
881	        }
882	        HttpHeaders headers = new HttpHeaders();
883	        Pet pet = petMapper.toPet(petFieldsDto);
884	        owner.setId(ownerId);
885	        pet.setOwner(owner);
886	        pet.getType().setName(null);
887	        this.clinicService.savePet(pet);
888	        PetDto petDto = petMapper.toPetDto(pet);
889	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
890	            .buildAndExpand(pet.getId()).toUri());
891	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
892	    }
893	
894	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
895	    @Override
896	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
897	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
898	        if (currentOwner != null) {
899	            Pet currentPet = this.clinicService.findPetById(petId);
900	            if (currentPet != null) {
901	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
902	                currentPet.setName(petFieldsDto.getName());
903	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
904	                this.clinicService.savePet(currentPet);
905	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
906	            }
907	        }
908	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
909	    }
910	
911	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
912	    @Override
913	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
914	        HttpHeaders headers = new HttpHeaders();
915	        Visit visit = visitMapper.toVisit(visitFieldsDto);
916	        Pet pet = new Pet();
917	        pet.setId(petId);
918	        visit.setPet(pet);
919	        this.clinicService.saveVisit(visit);
920	        VisitDto visitDto = visitMapper.toVisitDto(visit);
921	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
922	            .buildAndExpand(visit.getId()).toUri());
923	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
924	    }
925	
926	
927	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
928	    @Override
929	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
930	        Owner owner = this.clinicService.findOwnerById(ownerId);
931	        if (owner != null) {
932	            Pet pet = owner.getPet(petId);
933	            if (pet != null) {
934	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
935	            }
936	        }
937	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
938	    }
939	}
