1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.service.ClinicService;
13	
14	import java.time.LocalDate;
15	import java.time.Period;
16	import java.util.Collection;
17	import java.util.List;
18	import java.util.Map;
19	import java.util.Objects;
20	import java.util.OptionalInt;
21	import java.util.stream.Stream;
22	
23	/**
24	 * Maps Owner &amp; OwnerDto using Mapstruct
25	 */
26	@Mapper(uses = PetMapper.class)
27	public abstract class OwnerMapper {
28	
29	    /**
30	     * A create is flagged with {@code bulkSignupWarning=true} once more than this many owners have
31	     * already been created on the same registration date.
32	     */
33	    private static final int BULK_SIGNUP_THRESHOLD = 80;
34	
35	    @Autowired
36	    protected ClinicService clinicService;
37	
38	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
39	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
40	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
41	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
42	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
43	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
44	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
45	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
46	    @Mapping(target = "locality", expression = "java(locality(owner))")
47	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
48	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
49	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
50	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
51	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
52	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
53	    public abstract OwnerDto toOwnerDto(Owner owner);
54	
55	    /**
56	     * The month the fiscal year starts on (1 July).
57	     */
58	    private static final int FISCAL_YEAR_START_MONTH = 7;
59	
60	    /**
61	     * Derives the fiscal year (as an integer) of the given date. The fiscal year starts on 1 July,
62	     * so a date on or after 1 July belongs to the following calendar year's fiscal year (e.g.
63	     * 2026-07-01 is fiscal year 2027) while an earlier date takes the calendar year unchanged.
64	     */
65	    private int fiscalYearOf(LocalDate date) {
66	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
67	    }
68	
69	    /**
70	     * Derives the owner's {@code fiscalYear}, formatted {@code FY<YY>} where YY is the last two
71	     * digits of the fiscal year (starting 1 July) of the owner's business-day-adjusted
72	     * {@code registrationDate}. Returns {@code null} when no registration date is present.
73	     */
74	    protected String fiscalYear(Owner owner) {
75	        LocalDate registrationDate = owner.getRegistrationDate();
76	        if (registrationDate == null) {
77	            return null;
78	        }
79	        return String.format("FY%02d", fiscalYearOf(registrationDate) % 100);
80	    }
81	
82	    /**
83	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
84	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
85	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
86	     * the registration date (against which the age is measured) is absent.
87	     */
88	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
89	        LocalDate birthDate = owner.getBirthDate();
90	        LocalDate registrationDate = owner.getRegistrationDate();
91	        if (birthDate == null || registrationDate == null) {
92	            return null;
93	        }
94	        int age = Period.between(birthDate, registrationDate).getYears();
95	        if (age < 18) {
96	            return OwnerDto.AgeBandEnum.MINOR;
97	        }
98	        if (age < 65) {
99	            return OwnerDto.AgeBandEnum.ADULT;
100	        }
101	        return OwnerDto.AgeBandEnum.SENIOR;
102	    }
103	
104	    /**
105	     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
106	     * longest first so the correct code is matched before a shorter prefix of it. Australia
107	     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
108	     * endpoint normalizes against.
109	     */
110	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
111	
112	    /**
113	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
114	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
115	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
116	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
117	     */
118	    protected String telephoneDisplay(Owner owner) {
119	        String telephone = owner.getTelephone();
120	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
121	            return telephone;
122	        }
123	        String digits = telephone.substring(1);
124	        String countryCode = KNOWN_COUNTRY_CODES.stream()
125	            .filter(digits::startsWith)
126	            .findFirst()
127	            .orElse("");
128	        String national = digits.substring(countryCode.length());
129	        StringBuilder grouped = new StringBuilder();
130	        for (int i = 0; i < national.length(); i++) {
131	            if (i > 0 && i % 3 == 0) {
132	                grouped.append(' ');
133	            }
134	            grouped.append(national.charAt(i));
135	        }
136	        return "+" + countryCode + " " + grouped;
137	    }
138	
139	    /**
140	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key:
141	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A {@code null}
142	     * email or householdId contributes an empty segment.
143	     */
144	    protected String identityKey(Owner owner) {
145	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
146	        String email = owner.getEmail() == null ? "" : owner.getEmail();
147	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
148	        return telephone + "|" + email + "|" + householdId;
149	    }
150	
151	    /**
152	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
153	     * present, otherwise {@code PHONE}.
154	     */
155	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
156	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
157	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
158	    }
159	
160	    /**
161	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
162	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
163	     */
164	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
165	        "NSW", new int[] {2000, 2099},
166	        "VIC", new int[] {3000, 3099},
167	        "QLD", new int[] {4000, 4099});
168	
169	    /**
170	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
171	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
172	     * moves in lockstep with the identity assigned on create. When no customer code has been
173	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
174	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
175	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
176	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
177	     */
178	    protected String locality(Owner owner) {
179	        String customerCode = owner.getCustomerCode();
180	        if (customerCode != null) {
181	            int dash = customerCode.indexOf('-');
182	            if (dash > 0) {
183	                return customerCode.substring(0, dash);
184	            }
185	        }
186	        String fromPostcode = regionFromPostcode(owner.getPostcode());
187	        if (fromPostcode != null) {
188	            return fromPostcode;
189	        }
190	        String city = owner.getCity();
191	        if (city == null) {
192	            return "UNKNOWN";
193	        }
194	        return switch (city) {
195	            case "Sydney" -> "NSW";
196	            case "Melbourne" -> "VIC";
197	            case "Brisbane" -> "QLD";
198	            default -> "UNKNOWN";
199	        };
200	    }
201	
202	    /**
203	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
204	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
205	     */
206	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
207	        "NSW", "Australia/Sydney",
208	        "VIC", "Australia/Melbourne",
209	        "QLD", "Australia/Brisbane");
210	
211	    /**
212	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
213	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
214	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
215	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
216	     */
217	    protected String timezone(Owner owner) {
218	        return REGION_TIMEZONE.get(locality(owner));
219	    }
220	
221	    /**
222	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
223	     * the postcode is absent, not 4 digits, or in no known range.
224	     */
225	    private String regionFromPostcode(String postcode) {
226	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
227	            return null;
228	        }
229	        int value = Integer.parseInt(postcode);
230	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
231	            int[] range = entry.getValue();
232	            if (value >= range[0] && value <= range[1]) {
233	                return entry.getKey();
234	            }
235	        }
236	        return null;
237	    }
238	
239	    /**
240	     * The minimum household size (counting the owner itself) that earns household membership
241	     * points.
242	     */
243	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
244	
245	    /**
246	     * An owner's tenure must span strictly more than this many elapsed fiscal years to earn the
247	     * tenure membership points. A newly created owner has zero elapsed fiscal years and so never
248	     * clears this threshold.
249	     */
250	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
251	
252	    /**
253	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
254	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
255	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
256	     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
257	     */
258	    protected Integer membershipPoints(Owner owner) {
259	        int points = 0;
260	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
261	        if (hasEmail) {
262	            points += 2;
263	        }
264	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
265	        if (noNamesakes) {
266	            points += 1;
267	        }
268	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
269	            points += 2;
270	        }
271	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
272	            points += 3;
273	        }
274	        return points;
275	    }
276	
277	    /**
278	     * Derives the owner's membership level, capped by their household. The level starts from the
279	     * owner's own {@link #uncappedMembershipLevel(Owner) points-based level} but may not exceed one
280	     * above the current maximum level among the owner's existing household members (other owners
281	     * sharing its {@code householdId}). When the owner has no existing household member no cap
282	     * applies and the points-based level is returned unchanged.
283	     */
284	    protected Integer membershipLevel(Owner owner) {
285	        int level = uncappedMembershipLevel(owner);
286	        OptionalInt maxHouseholdLevel = otherHouseholdMembers(owner)
287	            .mapToInt(this::uncappedMembershipLevel)
288	            .max();
289	        if (maxHouseholdLevel.isEmpty()) {
290	            return level;
291	        }
292	        return Math.min(level, maxHouseholdLevel.getAsInt() + 1);
293	    }
294	
295	    /**
296	     * The owner's points-based membership level, before the household ceiling is applied: level 1
297	     * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more (see
298	     * {@link #membershipPoints(Owner) membership points}). The household members' maximum against
299	     * which {@link #membershipLevel(Owner)} caps is measured with this uncapped value, so mutual
300	     * household members do not recurse into each other's caps.
301	     */
302	    private int uncappedMembershipLevel(Owner owner) {
303	        int points = membershipPoints(owner);
304	        if (points <= 1) {
305	            return 1;
306	        }
307	        if (points <= 3) {
308	            return 2;
309	        }
310	        if (points <= 5) {
311	            return 3;
312	        }
313	        return 4;
314	    }
315	
316	    /**
317	     * The owner's existing household members: every other owner (excluding the owner itself) sharing
318	     * its {@code householdId}. Empty when the owner has no household identifier or is the sole member
319	     * of its household.
320	     */
321	    private Stream<Owner> otherHouseholdMembers(Owner owner) {
322	        String householdId = owner.getHouseholdId();
323	        if (householdId == null) {
324	            return Stream.empty();
325	        }
326	        return this.clinicService.findAllOwners().stream()
327	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
328	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()));
329	    }
330	
331	    /**
332	     * The number of owners in this owner's household — the count of owners (including this one)
333	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
334	     */
335	    private long householdSize(Owner owner) {
336	        String householdId = owner.getHouseholdId();
337	        if (householdId == null) {
338	            return 0;
339	        }
340	        return this.clinicService.findAllOwners().stream()
341	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
342	            .count();
343	    }
344	
345	    /**
346	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
347	     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
348	     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
349	     * owner without a registration date is treated as having no tenure.
350	     */
351	    private long tenureFiscalYears(Owner owner) {
352	        LocalDate registrationDate = owner.getRegistrationDate();
353	        if (registrationDate == null) {
354	            return 0;
355	        }
356	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
357	    }
358	
359	    /**
360	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
361	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
362	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
363	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
364	     * owner has no registration date.
365	     */
366	    protected Boolean bulkSignupWarning(Owner owner) {
367	        LocalDate registrationDate = owner.getRegistrationDate();
368	        if (registrationDate == null) {
369	            return false;
370	        }
371	        long othersOnDay = this.clinicService.findAllOwners().stream()
372	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
373	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
374	            .count();
375	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
376	    }
377	
378	    /**
379	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the digits
380	     * contained in the owner's {@code customerCode}. Non-digit characters are ignored. Returns
381	     * {@code null} when no customer code has been assigned.
382	     */
383	    protected Integer checkDigit(Owner owner) {
384	        String customerCode = owner.getCustomerCode();
385	        if (customerCode == null) {
386	            return null;
387	        }
388	        int sum = 0;
389	        boolean dbl = true;
390	        for (int i = customerCode.length() - 1; i >= 0; i--) {
391	            char c = customerCode.charAt(i);
392	            if (c < '0' || c > '9') {
393	                continue;
394	            }
395	            int d = c - '0';
396	            if (dbl) {
397	                d *= 2;
398	                if (d > 9) {
399	                    d -= 9;
400	                }
401	            }
402	            sum += d;
403	            dbl = !dbl;
404	        }
405	        return (10 - (sum % 10)) % 10;
406	    }
407	
408	    /**
409	     * Derives the owner's {@code salutation}: the owner's {@code title} and {@code lastName}
410	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
411	     * title was supplied (a {@code null} or blank title).
412	     */
413	    protected String salutation(Owner owner) {
414	        String title = owner.getTitle();
415	        String lastName = owner.getLastName();
416	        if (title == null || title.isBlank()) {
417	            return lastName;
418	        }
419	        return title + " " + lastName;
420	    }
421	
422	    /**
423	     * Derives the owner's {@code selfLink}: the canonical link to this owner resource, formatted
424	     * {@code /api/owners/<id>} using the owner's id. Returns {@code null} when the owner has no id.
425	     */
426	    protected String selfLink(Owner owner) {
427	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
428	    }
429	
430	    public abstract Owner toOwner(OwnerDto ownerDto);
431	
432	    @Mapping(target = "id", ignore = true)
433	    @Mapping(target = "pets", ignore = true)
434	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
435	
436	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
437	
438	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
439	
440	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
441	        OwnerPageDto ownerPageDto = new OwnerPageDto();
442	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
443	        ownerPageDto.setPage(ownerPage.getNumber());
444	        ownerPageDto.setSize(ownerPage.getSize());
445	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
446	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
447	        return ownerPageDto;
448	    }
449	}
